8px 0 22px}.activation-card label{display:grid;gap:7px;margin-bottom:13px}.form-message{padding:11px;border-radius:12px;background:#eef3e9;color:var(--brand-2);font-size:11px;line-height:1.5;margin-top:12px}.small-link.center{display:flex;margin:18px auto 0}.year-select{min-width:100px}
