/* =========================================================
   ARUNIKA CINEMATIC UI — streaming-inspired redesign
   ========================================================= */
:root{
  --bg:#070707;
  --bg-soft:#101010;
  --surface:#171717;
  --surface-2:#202020;
  --surface-3:#2a2a2a;
  --surface-hover:#2f2f2f;
  --text:#f5f5f5;
  --muted:#b3b3b3;
  --muted-2:#777;
  --brand:#e50914;
  --brand-2:#ff2b35;
  --brand-dark:#b20710;
  --line:rgba(255,255,255,.09);
  --line-strong:rgba(255,255,255,.16);
  --shadow:0 18px 60px rgba(0,0,0,.52);
  --radius:10px;
  --radius-lg:16px;
}
*{box-sizing:border-box}
html{background:var(--bg);color-scheme:dark}
body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;letter-spacing:-.01em}
button,input,select,textarea{font:inherit}
button,a{ -webkit-tap-highlight-color:transparent }
a{color:inherit;text-decoration:none}
img{display:block;max-width:100%}
.hidden{display:none!important}
.panel{background:linear-gradient(145deg,rgba(31,31,31,.98),rgba(20,20,20,.98));border:1px solid var(--line);box-shadow:none;border-radius:var(--radius-lg)}
.eyebrow,.section-tag{color:#d5d5d5;font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}
.muted{color:var(--muted)!important}
.progress{height:4px;background:#4a4a4a;border-radius:999px;overflow:hidden}
.progress span,.media-progress span,.fake-progress span{display:block;height:100%;background:var(--brand);border-radius:inherit}
.primary-btn,.netflix-play{display:inline-flex;align-items:center;justify-content:center;gap:9px;border:0;border-radius:5px;background:#fff;color:#111;padding:11px 18px;font-weight:800;cursor:pointer;transition:.18s ease}
.primary-btn:hover,.netflix-play:hover{background:#d9d9d9;transform:translateY(-1px)}
.ghost-btn,.netflix-more{display:inline-flex;align-items:center;justify-content:center;gap:9px;border:0;border-radius:5px;background:rgba(109,109,110,.72);color:#fff;padding:11px 18px;font-weight:750;cursor:pointer;backdrop-filter:blur(8px);transition:.18s ease}
.ghost-btn:hover,.netflix-more:hover{background:rgba(109,109,110,.48)}
.small-link,.text-btn{background:transparent;border:0;color:#c7c7c7;display:inline-flex;align-items:center;gap:5px;cursor:pointer}
.small-link:hover,.text-btn:hover{color:#fff}
.icon-btn,.nav-icon-btn{display:inline-flex;align-items:center;justify-content:center;border:0;background:transparent;color:#fff;cursor:pointer}
.icon-btn{width:38px;height:38px;border-radius:50%}
.icon-btn:hover,.nav-icon-btn:hover{background:rgba(255,255,255,.08)}
.info-dot{width:21px;height:21px;border:2px solid currentColor;border-radius:50%;display:grid;place-items:center;font-family:Georgia,serif;font-weight:800}
.status-pill{padding:5px 8px;border-radius:4px;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;background:#333;color:#eee}
.status-pill.reading,.status-pill.watching{background:rgba(229,9,20,.92)}
.status-pill.finished{background:#2b6f4c}
.status-pill.wishlist{background:#56447b}
.status-pill.unfinished{background:#474747}
.rating{color:#f0cf73}

/* App navigation */
.app-shell.stream-app{min-height:100vh;background:#070707;color:#fff}
.stream-nav{position:fixed;z-index:90;top:0;left:0;right:0;height:68px;padding:0 clamp(18px,4vw,60px);display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(0,0,0,.96),rgba(0,0,0,.72) 68%,transparent);transition:background .25s}
.stream-nav-left,.stream-nav-actions{display:flex;align-items:center;gap:24px}
.stream-wordmark{border:0;background:transparent;color:var(--brand);font-size:24px;font-weight:1000;letter-spacing:-.06em;cursor:pointer}
.stream-nav-links{display:flex;align-items:center;gap:20px}
.stream-nav-links button{border:0;background:transparent;color:#d8d8d8;font-size:13px;font-weight:500;cursor:pointer;padding:8px 0;transition:.16s}
.stream-nav-links button:hover,.stream-nav-links button.active{color:#fff}
.stream-nav-links button.active{font-weight:800}
.stream-nav-actions{gap:10px}
.nav-icon-btn{width:38px;height:38px;border-radius:50%}
.desktop-install{border:0;background:transparent;color:#e9e9e9;font-size:12px;cursor:pointer}
.stream-pro-pill,.stream-pro-active{display:inline-flex;align-items:center;gap:5px;padding:7px 10px;border-radius:4px;font-size:11px;font-weight:900}
.stream-pro-pill{background:var(--brand)}
.stream-pro-active{background:#1f6b45;color:#eafff2}
.profile-avatar{width:34px;height:34px;border:0;border-radius:5px;background:linear-gradient(135deg,#872424,#d63232);color:#fff;font-weight:900;cursor:pointer}
.stream-menu-btn{display:none}
.stream-main{min-height:100vh;padding-top:68px;background:#070707}
.stream-page-title{padding:42px clamp(20px,4vw,60px) 14px;display:flex;align-items:end;justify-content:space-between}
.stream-page-title span{font-size:10px;letter-spacing:.18em;font-weight:900;color:#aaa}
.stream-page-title h1{margin:6px 0 0;font-size:clamp(28px,3vw,46px);letter-spacing:-.04em}
.stream-page-actions button{display:flex;align-items:center;gap:7px;border:1px solid var(--line-strong);background:#181818;color:#fff;padding:9px 13px;border-radius:5px;cursor:pointer}
.mobile-drawer,.drawer-backdrop{display:none}

/* Cinematic home */
.stream-home{min-height:100vh;background:#070707;overflow:hidden}
.stream-hero{position:relative;min-height:min(78vh,780px);display:flex;align-items:center;padding:110px clamp(20px,5vw,72px) 150px;background-size:cover;background-position:center 24%;isolation:isolate}
.stream-hero.no-cover{background:
 radial-gradient(circle at 76% 34%,rgba(229,9,20,.38),transparent 24%),
 radial-gradient(circle at 65% 48%,rgba(91,20,74,.55),transparent 28%),
 linear-gradient(115deg,#070707 12%,#171113 48%,#090909 78%)}
.stream-hero.no-cover:before{content:"A";position:absolute;right:8vw;top:12%;font-size:min(45vw,520px);line-height:.8;font-weight:1000;letter-spacing:-.12em;color:rgba(255,255,255,.035);z-index:-1}
.stream-hero:after{content:"";position:absolute;inset:auto 0 0;height:42%;background:linear-gradient(0deg,#070707 8%,rgba(7,7,7,.94) 22%,transparent);pointer-events:none}
.stream-hero-content{width:min(650px,58vw);position:relative;z-index:2}
.hero-brandline{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:900;letter-spacing:.14em;color:#d4d4d4;margin-bottom:20px}
.hero-a{display:grid;place-items:center;width:26px;height:26px;border-radius:3px;background:var(--brand);color:#fff;font-size:17px;letter-spacing:-.08em}
.hero-kicker{font-size:16px;font-weight:800;margin-bottom:7px;color:#fff}
.stream-hero h2{font-size:clamp(48px,6vw,92px);line-height:.92;letter-spacing:-.065em;margin:0 0 18px;max-width:11ch;text-wrap:balance}
.stream-hero p{font-size:clamp(15px,1.4vw,19px);line-height:1.55;color:#e7e7e7;max-width:610px;text-shadow:0 2px 12px #000;margin:0 0 22px}
.hero-meta{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px;font-size:13px;color:#d7d7d7}
.hero-meta b{color:#4bc47a}
.hero-meta span+span:before{content:"•";margin-right:10px;color:#777}
.stream-hero-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.hero-progress{width:min(380px,100%);margin-top:20px}
.hero-progress small{display:block;margin-top:7px;color:#bdbdbd;font-size:11px}
.hero-quick-stats{position:absolute;right:clamp(20px,5vw,72px);bottom:125px;display:flex;gap:1px;z-index:3;background:rgba(20,20,20,.72);backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,.1);border-radius:6px;overflow:hidden}
.hero-quick-stats div{padding:13px 18px;min-width:104px}
.hero-quick-stats div+div{border-left:1px solid rgba(255,255,255,.09)}
.hero-quick-stats strong{display:block;font-size:19px}
.hero-quick-stats span{font-size:10px;color:#aaa;text-transform:uppercase;letter-spacing:.08em}

.stream-rows{position:relative;z-index:5;margin-top:-105px;padding-bottom:70px}
.media-rail{padding:0 clamp(20px,4vw,60px);margin:0 0 34px}
.rail-heading{display:flex;align-items:center;justify-content:space-between;margin:0 0 10px}
.rail-heading h3{font-size:clamp(18px,2vw,25px);margin:0;letter-spacing:-.025em}
.rail-heading button{opacity:0;border:0;background:transparent;color:#54b9c5;font-size:12px;display:flex;align-items:center;gap:3px;cursor:pointer;transition:.2s}
.media-rail:hover .rail-heading button{opacity:1}
.rail-track{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(190px,16vw);gap:7px;overflow-x:auto;overflow-y:visible;scrollbar-width:none;padding:8px 0 20px}
