/* Slightly soften every surface when themes switch */
@media (prefers-reduced-motion:no-preference){
  .panel,.media-card,.book-tile,.learning-tile,.stream-nav,.landing-stream-nav,
  .theme-toggle,.install-app-btn,.modal-card,.toolbar,.day{
    transition:background-color .22s ease,color .22s ease,border-color .22s ease,box-shadow .22s ease,transform .18s ease;
  }
}


/* =========================================================
   PRECISION PASS — landing, portrait, light theme, forms
   ========================================================= */
:root{
  --landing-gutter:clamp(20px,6vw,96px);
}

/* Landing alignment + clean hero-to-library transition */
.landing-stream-nav{
  position:fixed;
  top:0;
  left:0;
  right:0;
  width:100%;
  height:68px;
  padding:0 var(--landing-gutter);
  z-index:140;
  background:linear-gradient(180deg,rgba(0,0,0,.96),rgba(0,0,0,.76) 72%,rgba(0,0,0,.18));
}
.landing-stream-nav .landing-wordmark{flex:0 0 auto}
.landing-stream-nav nav{min-width:0}
.landing-nav-actions{margin-left:auto;flex:0 0 auto}

.landing-cinema-hero{
  min-height:100svh;
  overflow:hidden;
  padding:112px var(--landing-gutter) 132px;
  background:#070707;
}
.landing-cinema-hero .cinema-grid{
  inset:0 0 88px 0;
  transform:scale(1.025);
}
.landing-cinema-hero .cinema-vignette{
  background:
    linear-gradient(90deg,rgba(0,0,0,.98) 0%,rgba(0,0,0,.86) 42%,rgba(0,0,0,.2) 72%,rgba(0,0,0,.72) 100%),
    linear-gradient(0deg,#070707 0%,rgba(7,7,7,.98) 11%,rgba(7,7,7,.74) 26%,transparent 52%,rgba(0,0,0,.23) 100%);
}
.landing-cinema-hero:after{
  content:"";
  position:absolute;
  z-index:-1;
  left:0;
  right:0;
  bottom:0;
  height:205px;
  pointer-events:none;
  background:linear-gradient(0deg,#070707 0%,#070707 30%,rgba(7,7,7,.92) 56%,transparent 100%);
}
.landing-cinema-copy{
  width:min(780px,61vw);
  max-width:780px;
}
.landing-cinema-copy h1{
  max-width:11.5ch;
  font-size:clamp(54px,6.2vw,96px);
  line-height:.93;
  letter-spacing:-.068em;
  margin:14px 0 24px;
}
.landing-cinema-copy>p{
  max-width:700px;
  margin:0;
  font-size:clamp(15px,1.35vw,20px);
  line-height:1.58;
}
.landing-actions{
  margin-top:28px;
  gap:9px;
}
.landing-actions>a,
.landing-actions>button{
  min-height:48px;
  padding-left:19px;
  padding-right:19px;
}
.landing-proof{
  width:min(720px,100%);
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:18px;
  margin-top:30px;
}
.landing-proof-item{
  min-width:0;
  border-left:2px solid #e50914;
  padding:3px 0 3px 11px;
}
.landing-proof-item b,
.landing-proof-item span{
  display:block;
}
.landing-proof-item b{
  color:#fff;
  font-size:11px;
  letter-spacing:.01em;
}
.landing-proof-item span{
  margin-top:4px;
  color:#9e9e9e;
  font-size:10px;
  line-height:1.35;
}

.landing-stream-section{
  width:100%;
  padding:76px var(--landing-gutter) 70px;
  overflow:hidden;
  background:#070707;
}
.landing-stream-section + .landing-stream-section{padding-top:62px}
.landing-section-head{
  width:min(890px,100%);
  max-width:890px;
  margin:0 0 28px;
}
.landing-section-head .section-tag{
  display:block;
  margin-bottom:11px;
}
.landing-section-head h2{
  max-width:14ch;
  margin:0 0 16px;
  font-size:clamp(39px,4.4vw,68px);
  line-height:.98;
  letter-spacing:-.052em;
  text-wrap:balance;
}
.landing-section-head p{
  width:min(720px,100%);
  margin:0;
  font-size:14px;
  line-height:1.55;
}
.landing-rail{
  width:100%;
  margin:0;
  padding:4px 0 24px;
  gap:10px;
}
.book-cover-rail{
  grid-auto-columns:clamp(150px,12.2vw,205px);
}
.landing-media-card{
  min-width:0;
}
.landing-media-card>strong{
  margin-top:9px;
  font-size:12px;
}
.landing-media-card>span{
  margin-top:3px;
  font-size:9px;
}
.landing-learning-grid{gap:12px}
.landing-feature-showcase,
.landing-pro-section{
  padding-left:var(--landing-gutter);
  padding-right:var(--landing-gutter);
}
.stream-footer{
  padding-left:var(--landing-gutter);
  padding-right:var(--landing-gutter);
}

/* App topbar: desktop controls stay clear; phone controls move to drawer */
.desktop-theme-control,
.desktop-install-control{
  display:flex;
  align-items:center;
}
.drawer-utility{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:7px;
  margin:0 0 16px;
}
.drawer-utility .theme-toggle,
.drawer-utility .install-app-btn{
  width:100%;
}
.drawer-utility:empty{display:none}

/* Install should never occupy a phantom slot when hidden */
.install-app-btn[hidden]{display:none!important}

/* Simplified forms */
.compact-form{gap:12px}
.form-advanced{
  margin-top:16px;
  border:1px solid #303030;
  border-radius:6px;
  background:#111;
  overflow:hidden;
}
.form-advanced summary{
  list-style:none;
  cursor:pointer;
  padding:13px 15px;
  color:#b7b7b7;
  font-size:10px;
  font-weight:800;
  letter-spacing:.04em;
  display:flex;
  align-items:center;
  justify-content:space-between;
}
.form-advanced summary::-webkit-details-marker{display:none}
.form-advanced summary:after{
  content:"+";
  width:22px;
  height:22px;
  display:grid;
  place-items:center;
  border-radius:50%;
  background:#242424;
  color:#fff;
  font-size:15px;
}
.form-advanced[open] summary:after{content:"−"}
.advanced-grid{
  padding:0 14px 14px;
  border-top:1px solid #242424;
  padding-top:14px;
}
.compact-cover-preview{
  display:flex;
  align-items:center;
  gap:10px;
  min-height:76px;
}
.compact-cover-preview img{
  width:48px;
  height:68px;
  border-radius:4px;
  object-fit:cover;
}
.compact-cover-preview span{
  color:#858585;
  font-size:9px;
}
.page-range-fields{grid-column:1/-1}

/* Missing light-mode surface audit */
html[data-theme="light"] .form-advanced{
  background:#f8f5f1;
  border-color:#ddd6ce;
