import type { Metadata } from "next";
import { ArunikaApp } from "@/components/ArunikaApp";

export const metadata: Metadata = { title: "Aplikasi" };
export default function AppPage(){ return <ArunikaApp />; }

"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import { Icon } from "@/components/Icon";
import { purchasePublic } from "@/lib/backend";

type Method = {
  id:string;
  type:"bank"|"ewallet"|"qris"|"other";
  label:string;
  account_name?:string|null;
  account_number?:string|null;
  instructions?:string|null;
};

type Order = {
  id:string;
  order_code:string;
  buyer_name:string;
  whatsapp:string;
  email:string;
  amount:number;
  status:string;
  payment_method_snapshot?:Method|null;
};

const money=(n:number)=>new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",maximumFractionDigits:0}).format(n||0);

export default function ProPage(){
  const [methods,setMethods]=useState<Method[]>([]);
  const [price,setPrice]=useState(25000);
  const [buyerName,setBuyerName]=useState("");
  const [whatsapp,setWhatsapp]=useState("");
  const [email,setEmail]=useState("");
  const [methodId,setMethodId]=useState("");
  const [order,setOrder]=useState<Order|null>(null);
  const [accessToken,setAccessToken]=useState("");
  const [busy,setBusy]=useState(false);
  const [message,setMessage]=useState("");

  const selected=useMemo(()=>methods.find(m=>m.id===methodId)||order?.payment_method_snapshot||null,[methods,methodId,order]);

  useEffect(()=>{
    (async()=>{
      try{
        const cfg=await purchasePublic("config");
        if(cfg?.ok){
          setMethods(cfg.paymentMethods||[]);
          setPrice(Number(cfg.config?.price)||20000);
          if(cfg.paymentMethods?.[0]?.id)setMethodId(cfg.paymentMethods[0].id);
        }
        const saved=localStorage.getItem("arunika_purchase");
        if(saved){
          const p=JSON.parse(saved);
          if(p.orderCode&&p.accessToken){
            const status=await purchasePublic("status",{orderCode:p.orderCode,accessToken:p.accessToken});
            if(status?.ok){
              setOrder(status.order);
              setAccessToken(p.accessToken);
            }
          }
        }
      }catch{}
    })();
  },[]);

  async function createOrder(e:FormEvent){
    e.preventDefault();
    setBusy(true);setMessage("");
    try{
      const res=await purchasePublic("create",{buyerName,whatsapp,email,paymentMethodId:methodId});
      if(!res?.ok)throw new Error(res?.message||res?.code||"Order gagal dibuat.");
      setOrder(res.order);setAccessToken(res.accessToken);
      localStorage.setItem("arunika_purchase",JSON.stringify({orderCode:res.order.order_code,accessToken:res.accessToken}));
      setMessage("Pesanan berhasil dibuat. Lakukan pembayaran sesuai metode yang dipilih.");
    }catch(error){setMessage(String((error as Error)?.message||error))}
    finally{setBusy(false)}
  }

  async function confirmPaid(){
    if(!order||!accessToken)return;
    setBusy(true);setMessage("");
    try{
      const res=await purchasePublic("confirmPaid",{orderCode:order.order_code,accessToken});
      if(!res?.ok)throw new Error(res?.message||res?.code||"Konfirmasi gagal.");
      setOrder(res.order);
      setMessage("Konfirmasi pembayaran sudah dikirim. Admin akan memeriksa pembayaran lalu kode aktivasi dikirim ke email kamu.");
    }catch(error){setMessage(String((error as Error)?.message||error))}
    finally{setBusy(false)}
  }

  async function refreshStatus(){
    if(!order||!accessToken)return;
    setBusy(true);setMessage("");
    try{
      const res=await purchasePublic("status",{orderCode:order.order_code,accessToken});
      if(res?.ok){
        setOrder(res.order);
        if(res.order.status==="completed")setMessage("Pembayaran sudah selesai diproses. Cek email untuk kode aktivasi Arunika.");
        else if(res.order.status==="license_ready")setMessage("Lisensi sudah disiapkan. Email aktivasi sedang diproses.");
        else if(res.order.status==="awaiting_verification")setMessage("Pembayaran masih menunggu verifikasi admin.");
        else setMessage("Status pesanan diperbarui.");
      }
    }catch(error){setMessage(String((error as Error)?.message||error))}
    finally{setBusy(false)}
  }

  function resetOrder(){
    localStorage.removeItem("arunika_purchase");
    setOrder(null);setAccessToken("");setMessage("");
  }

  const features=["Koleksi buku tanpa batas","Learning tracker tanpa batas","Reading session & habit tracker","Knowledge vault & insights","Backup & restore data lokal","Lisensi maksimal 2 perangkat","PWA untuk HP dan laptop"];

  return <main className="simple-page pro-checkout-page">
    <a className="back-link" href="/">← Kembali ke Arunika</a>

    <section className="pro-checkout-hero">
      <div>
        <div className="eyebrow">ARUNIKA PRO</div>
        <h1>Upgrade sekali. Gunakan untuk perjalanan belajarmu.</h1>
        <p>Arunika Pro membuka koleksi tanpa batas dan akses penuh aplikasi. Pembayaran dan lisensi sekarang sudah terhubung ke backend Arunika.</p>
        <div className="price-line"><strong>{money(price)}</strong><span>sekali bayar</span></div>
        <ul className="pro-feature-list">{features.map(f=><li key={f}><Icon name="check" size={17}/>{f}</li>)}</ul>
        <a className="ghost-btn" href="/activate">Saya sudah punya kode aktivasi</a>
      </div>

      <div className="panel checkout-card">
        {!order ? <>
          <div className="checkout-head"><div><span className="eyebrow">CHECKOUT</span><h2>Beli Arunika Pro</h2></div><div className="checkout-price">{money(price)}</div></div>
          <form onSubmit={createOrder} className="checkout-form">
            <label><span>Nama lengkap</span><input required value={buyerName} onChange={e=>setBuyerName(e.target.value)} placeholder="Nama pembeli"/></label>
            <label><span>WhatsApp</span><input required value={whatsapp} onChange={e=>setWhatsapp(e.target.value)} placeholder="08xxxxxxxxxx" inputMode="tel"/></label>
            <label><span>Email</span><input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="nama@email.com"/></label>
            <div className="payment-label">Pilih metode pembayaran</div>
            <div className="payment-methods">
              {methods.map(m=><button type="button" key={m.id} className={methodId===m.id?"payment-choice active":"payment-choice"} onClick={()=>setMethodId(m.id)}>
                <span className={"payment-icon "+m.type}>{m.type==="qris"?"QR":m.label.slice(0,2).toUpperCase()}</span>
                <span><strong>{m.label}</strong><small>{m.type==="qris"?"QRIS":m.account_name||m.type}</small></span>
                <i>{methodId===m.id?"✓":""}</i>
              </button>)}
            </div>
            <button disabled={busy||!methodId} className="netflix-play checkout-submit">{busy?"Membuat pesanan…":"Lanjut ke Pembayaran"}</button>
          </form>
        </> : <>
          <div className="checkout-head"><div><span className="eyebrow">PESANAN</span><h2>{order.order_code}</h2></div><span className={"order-status "+order.status}>{order.status.replaceAll("_"," ")}</span></div>
          <div className="payment-summary">
            <div><span>Total</span><strong>{money(order.amount)}</strong></div>
            <div><span>Metode</span><strong>{order.payment_method_snapshot?.label||selected?.label||"-"}</strong></div>
          </div>
          {(order.status==="pending_payment"||order.status==="awaiting_verification")&&selected?<div className="transfer-box">
            <div className={"payment-big-icon "+selected.type}>{selected.type==="qris"?"QRIS":selected.label}</div>
            {selected.account_number?<div><span>Nomor / ID tujuan</span><strong className="account-number">{selected.account_number}</strong></div>:null}
            {selected.account_name?<div><span>Atas nama</span><strong>{selected.account_name}</strong></div>:null}
            {selected.instructions?<p>{selected.instructions}</p>:null}
          </div>:null}
          {order.status==="pending_payment"?<button className="netflix-play checkout-submit" disabled={busy} onClick={confirmPaid}>{busy?"Mengirim…":"Saya Sudah Bayar"}</button>:null}
          {order.status!=="pending_payment"?<button className="ghost-btn full" disabled={busy} onClick={refreshStatus}>{busy?"Memeriksa…":"Periksa Status Pesanan"}</button>:null}
          {order.status==="completed"?<a href="/activate" className="netflix-play checkout-submit">Aktifkan Arunika Pro <Icon name="arrow" size={17}/></a>:null}
          <button className="checkout-reset" type="button" onClick={resetOrder}>Buat pesanan baru</button>
        </>}
        {message?<div className="checkout-message">{message}</div>:null}
      </div>
    </section>
  </main>;
}

"use client";

import { FormEvent, useEffect, useState } from "react";
import { Icon } from "@/components/Icon";
import { clearStore, getOne, putOne, seedIfNeeded } from "@/lib/db";
import type { Settings } from "@/lib/types";
import { activateArunikaLicense } from "@/lib/backend";

export default function ActivatePage(){
  const [license,setLicense]=useState("");
  const [pin,setPin]=useState("");
  const [message,setMessage]=useState("");
  const [success,setSuccess]=useState(false);
  const [busy,setBusy]=useState(false);

  useEffect(()=>{seedIfNeeded()},[]);

  async function submit(e:FormEvent){
    e.preventDefault();
    setBusy(true);
    setMessage("");
    setSuccess(false);

    const normalized=license.trim().toUpperCase();
    if(!/^[A-Z0-9]{3,12}-[A-Z0-9]{4}-[A-Z0-9]{4}-[A-Z0-9]{4}$/.test(normalized)){
      setMessage("Format kode lisensi belum valid.");
      setBusy(false);
      return;
    }
    if(!/^\d{6}$/.test(pin)){
      setMessage("PIN aktivasi harus 6 digit.");
      setBusy(false);
      return;
    }

    try{
      const result=await activateArunikaLicense(normalized,pin);
      if(!result?.ok) throw new Error(result?.message||"Aktivasi gagal.");

      const current=await getOne<Settings>("settings","settings");
      if(current){
        await Promise.all([
          clearStore("books"),
          clearStore("learning"),
          clearStore("sessions"),
          clearStore("habit")
        ]);
        await putOne("settings",{
          ...current,
          activated:true,
          licenseCode:normalized,
          onboardingDone:false
        });
      }
      setSuccess(true);
      setMessage("Arunika Pro berhasil diaktifkan. Koleksi contoh Demo sudah dibersihkan dan aplikasi siap diisi dengan data milikmu.");
    }catch(error){
      const raw=String((error as Error)?.message||error);
      const friendly=raw.includes("PRODUCT_NOT_ENTITLED")
        ?"Kode ini tidak memiliki akses ke Arunika."
        :raw.includes("PIN_INVALID")
        ?"PIN aktivasi salah."
        :raw.includes("DEVICE_LIMIT")
        ?"Lisensi ini sudah mencapai batas perangkat."
        :raw.includes("NOT_FOUND")||raw.includes("tidak ditemukan")
        ?"Kode aktivasi tidak ditemukan."
        :raw.includes("DISABLED")
        ?"Lisensi sedang dinonaktifkan."
        :raw.includes("RATE_LIMIT")
        ?"Terlalu banyak percobaan. Coba lagi beberapa menit."
        :raw;
      setMessage(friendly||"Aktivasi belum berhasil.");
    }finally{
      setBusy(false);
    }
  }

  return <main className="simple-page auth-page">
    <a className="back-link" href="/">← Kembali ke Arunika</a>
    <section className="auth-layout">
      <div className="auth-copy">
        <div className="eyebrow">AKTIVASI ARUNIKA PRO</div>
        <h1>Aktivasi nyata. Lisensi terhubung ke backend.</h1>
        <p>Kode aktivasi dan PIN diverifikasi ke server Arunika, lalu lisensi diikat ke perangkat ini.</p>
        <div className="auth-points">
          <span><Icon name="lock" size={18}/> Kode + PIN diverifikasi server</span>
          <span><Icon name="check" size={18}/> Maksimal perangkat mengikuti lisensi</span>
          <span><Icon name="sparkles" size={18}/> Data Demo dibersihkan setelah aktivasi berhasil</span>
        </div>
      </div>

      <form className="panel activation-card" onSubmit={submit}>
        <div className="brand-symbol big">A</div>
        <h2>Aktivasi Pro</h2>
        <label>
          <span>Kode lisensi</span>
          <input value={license} onChange={e=>setLicense(e.target.value)} placeholder="ARUN-XXXX-XXXX-XXXX" autoCapitalize="characters"/>
        </label>
        <label>
          <span>PIN aktivasi</span>
          <input value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,""))} placeholder="6 digit dari email" type="password" inputMode="numeric" maxLength={6}/>
        </label>
        <button className="primary-btn large full" disabled={busy}>{busy?"Memverifikasi lisensi…":"Aktifkan Arunika Pro"}</button>
        {message?<div className={success?"form-message success-message":"form-message"}>{message}</div>:null}
        {success?<a className="netflix-play center" href="/app">Masuk ke Arunika <Icon name="arrow" size={15}/></a>:<a className="small-link center" href="/pro">Belum punya kode? Beli Pro</a>}
      </form>
    </section>
  </main>;
}

"use client";

import { FormEvent, useEffect, useState } from "react";
import { Icon } from "@/components/Icon";
import { adminLicenses, adminLogin, adminOrders } from "@/lib/backend";

type Order = {
  id:string; order_code:string; buyer_name:string; whatsapp:string; email:string;
  amount:number; status:string; created_at:string; payment_method_snapshot?:{label?:string}|null;
  final_email_sent_at?:string|null; final_email_error?:string|null;
};
type LicenseStats={total:number;active:number;reserved?:number;unused:number;disabled:number};

const money=(n:number)=>new Intl.NumberFormat("id-ID",{style:"currency",currency:"IDR",maximumFractionDigits:0}).format(n||0);

export default function AdminPage(){
  const [token,setToken]=useState("");
  const [pin,setPin]=useState("");
  const [orders,setOrders]=useState<Order[]>([]);
  const [orderStats,setOrderStats]=useState<any>(null);
  const [licenseStats,setLicenseStats]=useState<LicenseStats|null>(null);
  const [busy,setBusy]=useState(false);
  const [message,setMessage]=useState("");
  const [tab,setTab]=useState<"orders"|"licenses">("orders");

  useEffect(()=>{
    const saved=localStorage.getItem("arunika_admin_token")||"";
    if(saved){setToken(saved); void load(saved);}
  },[]);

  async function login(e:FormEvent){
    e.preventDefault();setBusy(true);setMessage("");
    try{
      const res=await adminLogin(pin);
      if(!res?.ok)throw new Error(res?.message||"PIN admin salah.");
      localStorage.setItem("arunika_admin_token",res.token);
      setToken(res.token);setPin("");
      await load(res.token);
    }catch(err){setMessage(String((err as Error)?.message||err))}
    finally{setBusy(false)}
  }

  async function load(t=token){
    if(!t)return;
    setBusy(true);setMessage("");
    try{
      const [o,l]=await Promise.all([adminOrders(t,"list"),adminLicenses(t,"list")]);
      if(o?.code==="UNAUTHORIZED"||l?.code==="UNAUTHORIZED")throw new Error("Sesi admin berakhir.");
      if(o?.ok){setOrders(o.orders||[]);setOrderStats(o.stats||null)}
      if(l?.ok)setLicenseStats(l.stats||null);
    }catch(err){
      const msg=String((err as Error)?.message||err);
      setMessage(msg);
      if(msg.includes("Sesi admin"))logout();
    }finally{setBusy(false)}
  }

  function logout(){
    localStorage.removeItem("arunika_admin_token");setToken("");setOrders([]);setOrderStats(null);setLicenseStats(null);
  }

  async function orderAction(action:string,orderId:string){
    setBusy(true);setMessage("");
    try{
      const res=await adminOrders(token,action,{orderId});
      if(!res?.ok)throw new Error(res?.message||res?.code||"Aksi gagal.");
      if(action==="assignLicense")setMessage(`Lisensi ${res.licenseCode||""}${res.activationPin?" · PIN "+res.activationPin:""} berhasil ditetapkan.${res.emailSent?" Email aktivasi terkirim.":res.emailError?" Email belum terkirim: "+res.emailError:""}`);
      else if(action==="resendEmail")setMessage(res.emailSent?"Email aktivasi dikirim ulang.":"Email gagal dikirim: "+(res.emailError||""));
      else setMessage("Pesanan diperbarui.");
      await load();
    }catch(err){setMessage(String((err as Error)?.message||err))}
    finally{setBusy(false)}
  }

  async function generate(count:number){
    setBusy(true);setMessage("");
    try{
      const res=await adminLicenses(token,"generate",{count});
      if(!res?.ok)throw new Error(res?.code||"Gagal membuat lisensi.");
      setMessage(`${res.licenses?.length||count} lisensi Arunika baru dibuat.`);
      await load();
    }catch(err){setMessage(String((err as Error)?.message||err))}
    finally{setBusy(false)}
  }

  if(!token)return <main className="admin-page admin-login-page">
    <a className="back-link" href="/">← Arunika</a>
    <form className="panel admin-login-card" onSubmit={login}>
      <div className="stream-wordmark">ARUNIKA</div>
      <span className="eyebrow">ADMIN CENTER</span>
      <h1>Masuk ke Admin Arunika</h1>
      <p>Gunakan PIN admin yang sudah terdaftar di backend universal.</p>
      <label><span>PIN Admin</span><input autoFocus type="password" inputMode="numeric" value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,""))} placeholder="••••••"/></label>
      <button className="netflix-play full" disabled={busy}>{busy?"Memverifikasi…":"Masuk Admin"}</button>
      {message?<div className="checkout-message">{message}</div>:null}
    </form>
  </main>;

  return <main className="admin-page">
    <header className="admin-topbar">
      <div><span className="stream-wordmark">ARUNIKA</span><small>ADMIN CENTER</small></div>
      <div className="admin-actions"><button onClick={()=>load()} disabled={busy}><Icon name="sparkles" size={16}/> Refresh</button><button onClick={logout}>Keluar</button></div>
    </header>

    <section className="admin-hero">
      <div><span className="eyebrow">PRODUCT · ARUNIKA</span><h1>Order & Lisensi</h1><p>Backend universal yang sama, data produk tetap dipisahkan berdasarkan product code.</p></div>
      <div className="admin-tabs"><button className={tab==="orders"?"active":""} onClick={()=>setTab("orders")}>Pesanan</button><button className={tab==="licenses"?"active":""} onClick={()=>setTab("licenses")}>Lisensi</button></div>
    </section>

    {message?<div className="admin-notice">{message}</div>:null}

    {tab==="orders"?<>
      <section className="admin-stat-grid">
        <AdminStat label="Total order" value={String(orderStats?.total??orders.length)}/>
        <AdminStat label="Menunggu verifikasi" value={String(orderStats?.awaiting??0)}/>
        <AdminStat label="Lisensi siap" value={String(orderStats?.ready??0)}/>
        <AdminStat label="Selesai" value={String(orderStats?.completed??0)}/>
      </section>

      <section className="panel admin-table-card">
        <div className="admin-card-head"><div><span className="eyebrow">PURCHASE ORDERS</span><h2>Pesanan terbaru</h2></div><span>{orders.length} order</span></div>
        <div className="admin-table-scroll">
          <table className="admin-table"><thead><tr><th>Order</th><th>Pembeli</th><th>Metode</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead>
          <tbody>{orders.map(o=><tr key={o.id}>
            <td><strong>{o.order_code}</strong><small>{new Date(o.created_at).toLocaleString("id-ID")}</small></td>
            <td><strong>{o.buyer_name}</strong><small>{o.email}</small></td>
            <td>{o.payment_method_snapshot?.label||"-"}</td>
            <td>{money(o.amount)}</td>
            <td><span className={"order-status "+o.status}>{o.status.replaceAll("_"," ")}</span>{o.final_email_error?<small className="email-error">{o.final_email_error}</small>:null}</td>
            <td><div className="table-actions">
              {o.status==="awaiting_verification"?<button className="approve" onClick={()=>orderAction("assignLicense",o.id)} disabled={busy}>Konfirmasi & Kirim Kode</button>:null}
              {(o.status==="license_ready"||o.status==="completed")?<button onClick={()=>orderAction("resendEmail",o.id)} disabled={busy}>Kirim Ulang Email</button>:null}
              {["pending_payment","awaiting_verification","license_ready"].includes(o.status)?<button className="danger" onClick={()=>orderAction("cancel",o.id)} disabled={busy}>Batalkan</button>:null}
            </div></td>
          </tr>)}
          {!orders.length?<tr><td colSpan={6} className="empty-table">Belum ada pesanan Arunika.</td></tr>:null}</tbody></table>
        </div>
      </section>
    </>:<>
      <section className="admin-stat-grid">
        <AdminStat label="Total lisensi" value={String(licenseStats?.total??0)}/>
        <AdminStat label="Stok belum dipakai" value={String(licenseStats?.unused??0)}/>
        <AdminStat label="Reserved" value={String(licenseStats?.reserved??0)}/>
        <AdminStat label="Aktif" value={String(licenseStats?.active??0)}/>
      </section>
      <section className="panel license-stock-card">
        <div><span className="eyebrow">LICENSE STOCK</span><h2>Stok kode Arunika</h2><p>Sistem order otomatis mengambil kode berstatus unused yang memiliki entitlement ARUNIKA.</p></div>
        <div className="license-actions"><button className="ghost-btn" onClick={()=>generate(10)} disabled={busy}>+ 10 Lisensi</button><button className="netflix-play" onClick={()=>generate(100)} disabled={busy}>+ 100 Lisensi</button></div>
      </section>
    </>}

    <footer className="admin-footer">ARUNIKA · Universal Licensing Backend</footer>
  </main>;
}

