export async function adminLicenses(token: string, action: string, payload: Record<string,unknown> = {}) {
  return postFunction("admin-license", { action, productCode: PRODUCT_CODE, ...payload }, token);
}

function hex(bytes: Uint8Array) {
  return Array.from(bytes).map((b)=>b.toString(16).padStart(2,"0")).join("");
}

async function sha256Hex(value: string) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return hex(new Uint8Array(digest));
}

function canonicalPublicJwk(jwk: JsonWebKey) {
  return JSON.stringify({ crv: jwk.crv, kty: jwk.kty, x: jwk.x, y: jwk.y });
}

export async function activateArunikaLicense(licenseCode: string, activationPin: string) {
  let deviceId = localStorage.getItem("arunika_device_id");
  let privateJwk: JsonWebKey | null = null;
  let publicJwk: JsonWebKey | null = null;

  try {
    const savedPrivate = localStorage.getItem("arunika_device_private_jwk");
    const savedPublic = localStorage.getItem("arunika_device_public_jwk");
    if (savedPrivate && savedPublic) {
      privateJwk = JSON.parse(savedPrivate);
      publicJwk = JSON.parse(savedPublic);
    }
  } catch {}

  if (!deviceId) {
    deviceId = crypto.randomUUID();
    localStorage.setItem("arunika_device_id", deviceId);
  }

  if (!privateJwk || !publicJwk) {
    const pair = await crypto.subtle.generateKey(
      { name: "ECDSA", namedCurve: "P-256" },
      true,
      ["sign", "verify"]
    ) as CryptoKeyPair;
    privateJwk = await crypto.subtle.exportKey("jwk", pair.privateKey);
    publicJwk = await crypto.subtle.exportKey("jwk", pair.publicKey);
    localStorage.setItem("arunika_device_private_jwk", JSON.stringify(privateJwk));
    localStorage.setItem("arunika_device_public_jwk", JSON.stringify(publicJwk));
  }

  const thumbprint = await sha256Hex(canonicalPublicJwk(publicJwk));
  const result = await postFunction("license-activate", {
    licenseCode: licenseCode.trim().toUpperCase(),
    productCode: PRODUCT_CODE,
    deviceId,
    deviceName: navigator.userAgent.includes("Mobile") ? "Arunika Mobile" : "Arunika Web",
    publicKey: publicJwk,
    publicKeyThumbprint: thumbprint,
    activationPin: activationPin.trim(),
  });

  if (!result?.ok) throw new Error(result?.message || result?.code || "Aktivasi gagal.");
  localStorage.setItem("arunika_license_certificate", JSON.stringify(result.certificate));
  localStorage.setItem("arunika_license_verification_key", JSON.stringify(result.verificationKey));
  localStorage.setItem("arunika_license_product", String(result.productCode || PRODUCT_CODE));
  localStorage.setItem("arunika_license_activated_at", new Date().toISOString());
  return result;
}

export async function verifyArunikaLicense() {
  const certRaw = localStorage.getItem("arunika_license_certificate");
  const privateRaw = localStorage.getItem("arunika_device_private_jwk");
  if (!certRaw || !privateRaw) return { ok:false, code:"NO_LOCAL_LICENSE" };

  const certificate = JSON.parse(certRaw);
  const privateJwk = JSON.parse(privateRaw) as JsonWebKey;
  const privateKey = await crypto.subtle.importKey(
    "jwk",
    privateJwk,
    { name:"ECDSA", namedCurve:"P-256" },
    false,
    ["sign"]
  );
  const nonce = crypto.randomUUID() + crypto.randomUUID();
  const payload = new TextEncoder().encode(certificate.signature + "." + nonce);
  const sig = await crypto.subtle.sign({name:"ECDSA",hash:"SHA-256"}, privateKey, payload);
  const bytes = new Uint8Array(sig);
  let raw = "";
  for (const b of bytes) raw += String.fromCharCode(b);
  const proof = btoa(raw).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");

  return postFunction("license-verify", { certificate, nonce, proof });
}

"use client";

import { demoBooks, demoHabit, demoLearning, demoSessions, demoSettings } from "./demo-data";
import type { BackupPayload, Book, HabitDay, LearningItem, ReadingSession, Settings } from "./types";

const DB_NAME = "arunika-local";
const VERSION = 1;
const STORES = ["books", "learning", "sessions", "habit", "settings"] as const;

type StoreName = (typeof STORES)[number];

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      for (const store of STORES) {
        if (!db.objectStoreNames.contains(store)) db.createObjectStore(store, { keyPath: "id" });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function tx<T>(storeName: StoreName, mode: IDBTransactionMode, runner: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(storeName, mode);
    const request = runner(transaction.objectStore(storeName));
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
    transaction.oncomplete = () => db.close();
    transaction.onerror = () => reject(transaction.error);
  });
}

export async function getAll<T>(storeName: StoreName): Promise<T[]> {
  return tx<T[]>(storeName, "readonly", (store) => store.getAll());
}

export async function getOne<T>(storeName: StoreName, id: string): Promise<T | undefined> {
  return tx<T | undefined>(storeName, "readonly", (store) => store.get(id));
}

export async function putOne<T extends { id: string }>(storeName: StoreName, value: T): Promise<T> {
  await tx<IDBValidKey>(storeName, "readwrite", (store) => store.put(value));
  return value;
}

export async function deleteOne(storeName: StoreName, id: string): Promise<void> {
  await tx<undefined>(storeName, "readwrite", (store) => store.delete(id) as IDBRequest<undefined>);
}

export async function clearStore(storeName: StoreName): Promise<void> {
  await tx<undefined>(storeName, "readwrite", (store) => store.clear() as IDBRequest<undefined>);
}

async function count(storeName: StoreName) {
  return tx<number>(storeName, "readonly", (store) => store.count());
}

export async function seedIfNeeded() {
  const existing = await getOne<Settings>("settings", "settings");
  if (existing) {
    if (!existing.activated && (existing.demoVersion || 0) < 3) {
      await Promise.all([
        ...demoBooks.map((item) => putOne("books", item)),
        ...demoLearning.map((item) => putOne("learning", item)),
        ...demoSessions.map((item) => putOne("sessions", item)),
        ...demoHabit.map((item) => putOne("habit", item)),
        putOne("settings", { ...existing, demoVersion: 3 })
      ]);
    }
    return;
  }
  await Promise.all([
    ...demoBooks.map((item) => putOne("books", item)),
    ...demoLearning.map((item) => putOne("learning", item)),
    ...demoSessions.map((item) => putOne("sessions", item)),
    ...demoHabit.map((item) => putOne("habit", item)),
    putOne("settings", { ...demoSettings, demoVersion: 3 })
  ]);
}

export async function loadSnapshot() {
  await seedIfNeeded();
  const [books, learning, sessions, habit, settings] = await Promise.all([
    getAll<Book>("books"),
    getAll<LearningItem>("learning"),
    getAll<ReadingSession>("sessions"),
    getAll<HabitDay>("habit"),
    getOne<Settings>("settings", "settings")
  ]);
  return { books, learning, sessions, habit, settings: settings ?? demoSettings };
}

export async function exportBackup(): Promise<BackupPayload> {
  const data = await loadSnapshot();
  return { version: 1, exportedAt: new Date().toISOString(), ...data };
}

export async function importBackup(payload: BackupPayload) {
  if (!payload || payload.version !== 1) throw new Error("Format backup tidak dikenali.");
  await Promise.all(STORES.map((store) => clearStore(store)));
  await Promise.all([
    ...payload.books.map((item) => putOne("books", item)),
    ...payload.learning.map((item) => putOne("learning", item)),
    ...payload.sessions.map((item) => putOne("sessions", item)),
    ...payload.habit.map((item) => putOne("habit", item)),
    putOne("settings", payload.settings)
  ]);
}

export function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

export function downloadJson(filename: string, data: unknown) {
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

